import axios from 'axios'

const api = axios.create({
  baseURL: 'http://localhost:8080/api',
})


api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token')
  if (token) {
    config.headers.Authorization = `Bearer ${token}`
  }
  return config
})

// If the backend ever rejects our token (expired/invalid), log the user
// out so they land back on the login screen instead of seeing broken pages.
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response && error.response.status === 401) {
      localStorage.removeItem('token')
      localStorage.removeItem('user')
      if (window.location.pathname !== '/login') {
        window.location.href = '/login'
      }
    }
    return Promise.reject(error)
  }
)

// Pulls a human-readable message out of an Axios error.
// The backend's GlobalExceptionHandler returns { error, status } on failure.
export function getErrorMessage(err, fallback = 'Something went wrong. Please try again.') {
  if (err?.response?.data?.error) return err.response.data.error
  if (err?.message === 'Network Error') return 'Cannot reach the server. Is the backend running on port 8080?'
  if (err?.message) return err.message
  return fallback
}

export default api
